{
  "assetSet": "local-task-board-assets",
  "version": "1.0.0",
  "createdFor": "local browser task board app",
  "runtime": {
    "requiresNetwork": false,
    "requiresBuildStep": false,
    "storage": "window.localStorage",
    "expectedEntryFile": "index.html"
  },
  "dataAssets": [
    {
      "id": "seed-tasks",
      "path": "assets/seed-tasks.json",
      "type": "application/json",
      "purpose": "Initial Todo/Doing/Done tasks used when localStorage has no saved board state.",
      "schema": {
        "root": "array",
        "requiredFields": [
          "id",
          "title",
          "description",
          "status",
          "priority",
          "createdAt",
          "updatedAt"
        ],
        "allowedStatuses": [
          "todo",
          "doing",
          "done"
        ],
        "allowedPriorities": [
          "low",
          "medium",
          "high"
        ]
      }
    }
  ],
  "uiAssetGuidance": {
    "css": {
      "recommendedFile": "style.css",
      "layout": "Three responsive columns labelled Todo, Doing, and Done.",
      "colors": {
        "pageBackground": "#f4f7fb",
        "panelBackground": "#ffffff",
        "primary": "#2563eb",
        "danger": "#dc2626",
        "text": "#172033",
        "mutedText": "#64748b"
      },
      "accessibility": [
        "Use visible focus states for form fields and buttons.",
        "Keep status controls labelled with their destination column.",
        "Use sufficient contrast for priority and action controls."
      ]
    },
    "javascript": {
      "recommendedFile": "script.js",
      "localStorageKey": "localTaskBoard.tasks.v1",
      "requiredWorkflows": [
        "load seed tasks when no localStorage value exists",
        "add a task to a selected status column",
        "edit title, description, status, and priority",
        "delete a task after user confirmation",
        "persist every mutation to localStorage",
        "render live task counts for Todo, Doing, and Done"
      ]
    },
    "html": {
      "recommendedFile": "index.html",
      "requiredLandmarks": [
        "main board region",
        "task form region",
        "Todo column",
        "Doing column",
        "Done column"
      ]
    }
  },
  "testAssetGuidance": {
    "recommendedPackageScript": "npm test",
    "minimumLocalChecks": [
      "index.html references style.css and script.js",
      "script.js contains the configured localStorage key",
      "all three statuses are represented",
      "seed task JSON is valid and includes Todo, Doing, and Done coverage"
    ]
  }
}
